use gg_ir::constant_fold::ConstantFoldPass; use gg_ir::{IrFunction, IrModule, IrValue, OpCode, pass::IrPass}; /// 测试 LoadConst(1) + LoadConst(2) 折叠为 LoadConst(3) #[test] fn test_fold_add_constants() { let mut module = IrModule::new("test"); let a_idx = module.add_constant(IrValue::Int(1)); let b_idx = module.add_constant(IrValue::Int(2)); module.add_function(IrFunction { name: "main".to_string(), param_count: 0, local_count: 0, instructions: vec![ OpCode::LoadConst(a_idx), OpCode::LoadConst(b_idx), OpCode::Add, OpCode::Return, ], }); let pass = ConstantFoldPass; let changed = pass.run(&mut module).unwrap(); assert!(changed); let func = &module.functions[0]; assert_eq!(func.instructions.len(), 2); match &func.instructions[0] { OpCode::LoadConst(idx) => { assert_eq!(module.constants[*idx], IrValue::Int(3)); } other => panic!("期望 LoadConst，实际: {:?}", other), } } /// 测试 LoadConst(true), Not 折叠为 LoadConst(false) #[test] fn test_fold_not_bool() { let mut module = IrModule::new("test"); let idx = module.add_constant(IrValue::Bool(true)); module.add_function(IrFunction { name: "main".to_string(), param_count: 0, local_count: 0, instructions: vec![ OpCode::LoadConst(idx), OpCode::Not, OpCode::Return, ], }); let pass = ConstantFoldPass; let changed = pass.run(&mut module).unwrap(); assert!(changed); let func = &module.functions[0]; assert_eq!(func.instructions.len(), 2); match &func.instructions[0] { OpCode::LoadConst(idx) => { assert_eq!(module.constants[*idx], IrValue::Bool(false)); } other => panic!("期望 LoadConst，实际: {:?}", other), } } /// 测试非常量表达式不会被折叠 #[test] fn test_non_constant_expressions_not_folded() { let mut module = IrModule::new("test"); let a_idx = module.add_constant(IrValue::Int(1)); module.add_function(IrFunction { name: "main".to_string(), param_count: 0, local_count: 1, instructions: vec![ OpCode::LoadConst(a_idx), OpCode::LoadLocal(0), OpCode::Add, OpCode::Return, ], }); let pass = ConstantFoldPass; let changed = pass.run(&mut module).unwrap(); assert!(!changed); let func = &module.functions[0]; assert_eq!(func.instructions.len(), 4); } 